          "component": "Icon",
          "name": "star"
        },
        {
          "id": "ratingText",
          "component": "Text",
          "text": "4.6 / 5.0"
        },
        {
          "id": "addressRow",
          "component": "Row",
          "align": "center",
          "children": [
            "locationIcon",
            "addressText"
          ]
        },
        {
          "id": "locationIcon",
          "component": "Icon",
          "name": "locationOn"
        },
        {
          "id": "addressText",
          "component": "Text",
          "text": "45 Bayard St, New York, NY 10013",
          "variant": "caption"
        },
        {
          "id": "cardDivider",
          "component": "Divider"
        },
        {
          "id": "bookButton",
