            "event": {
              "name": "book_table",
              "userMessage": "Book a table at Xi'an Famous Foods",
              "context": {
                "restaurantName": "Xi'an Famous Foods",
                "address": "45 Bayard St, New York, NY 10013"
              }
            }
          }
        },
        {
          "id": "btnText",
          "component": "Text",
          "text": "Book a Table"
        }
      ]
    }
  }
]
